25	export async function initializeChecklist(channel?: Channel) {
26	  try {
27	    const store = experimental_UniversalStore.create<StoreState, StoreEvent>({
28	      ...UNIVERSAL_CHECKLIST_STORE_OPTIONS,
29	      leader: true,
30	    });
31	
32	    const cache = createFileSystemCache({
33	      basePath: resolvePathInStorybookCache('checklist'),
34	      ns: 'storybook',
35	    });
36	
37	    const [[userState, saveUserState], [projectState, saveProjectState]] = await Promise.all([
38	      globalSettings().then((settings) => {
39	        const save = throttle(() => settings.save(), 1000);
40	        const state = {
41	          items: settings.value.checklist?.items ?? {},
42	          widget: settings.value.checklist?.widget ?? {},
43	        };
44	        const setState = ({
45	          items = state.items,
46	          widget = state.widget,
47	        }: {
48	          items?: typeof state.items;
49	          widget?: typeof state.widget;
50	        }) => {
51	          settings.value.checklist = { items, widget };
52	          save();
53	        };
54	        return [state, setState] as const;
55	      }),
56	
57	      cache.get<Pick<ChecklistState, 'items'>>('state').then((cachedState) => {
58	        const state = { items: cachedState?.items ?? {} };
59	        const setState = ({ items }: Pick<ChecklistState, 'items'>) =>
60	          cache.set('state', { items });
61	        return [state, setState] as const;
62	      }),
63	    ]);
64	
65	    // Load the checklist immediately so the UI is never blocked.
66	    store.setState(
67	      (value) =>
68	        ({
69	          ...toMerged(value, toMerged(userState, projectState)),
70	          loaded: true,
71	        }) satisfies StoreState
72	    );
73	
74	    // AI opt-in flag (set during `storybook init`). Non-blocking so a cache
75	    // failure cannot hide the checklist.
76	    getEventCacheEntry('ai-init-opt-in')
77	      .then((event) => {
78	        if (event) {
79	          store.setState((state) => ({ ...state, aiOptIn: true }));
80	        }
81	      })
82	      .catch(() => {});
83	
84	    // Mark the aiSetup item done if `storybook ai setup` has ever run. Called
85	    // at startup and on story index changes; errors are swallowed.
86	    const markAiSetupDone = async () => {
87	      try {
88	        const aiSetupEvent = await getEventCacheEntry('ai-setup');
89	        if (!aiSetupEvent) {
90	          return false;
91	        }
92	        if (store.getState().items.aiSetup?.status !== 'done') {
93	          store.setState((state) => ({
94	            ...state,
95	            items: {
96	              ...state.items,
97	              aiSetup: { ...state.items.aiSetup, status: 'done' },
98	            },
99	          }));
100	        }
101	        return true;
102	      } catch {
103	        return false;
104	      }
105	    };
106	
107	    // Debounced analytics + ghost stories: emit exactly once, 4 minutes after
108	    // activity stops. The timer resets on story-index changes, test-provider
109	    // state changes, and detected external vitest runs (`npx vitest`). We check
110	    // for `ai-setup` at idle time rather than eagerly, because the event is
111	    // cached AFTER `storybook ai setup` finishes its file writes.
112	    const AI_IDLE_DELAY_MS = 4 * 60 * 1000;
113	    let analyticsTimer: ReturnType<typeof setTimeout> | undefined;
114	    let analyticsEmitted = false;
115	
116	    // Story-index invalidations can arrive in flurries. Throttle the
117	    // fire-and-forget cache read so we don't hit disk on every tick. The
118	    // timer-internal markAiSetupDone() below is awaited separately.
119	    const throttledSyncAiSetupStatus = throttle(() => markAiSetupDone().catch(() => {}), 1000);
120	
121	    const scheduleIdleCheck = () => {
122	      if (!channel || analyticsEmitted) {
123	        return;
124	      }
125	      // Sync aiSetup UI immediately so the copy-prompt button disappears as
126	      // soon as setup completes, instead of after the 4-minute delay.
127	      throttledSyncAiSetupStatus();
128	      clearTimeout(analyticsTimer);
129	      analyticsTimer = setTimeout(async () => {
130	        if (!store.getState().aiOptIn) {
131	          return;
132	        }
133	        // Agents often run `npx vitest` for many minutes. If a recent
134	        // `test-run` or `ai-setup-self-healing-scoring` event is in the cache,
135	        // the agent is still active — reschedule. `CacheEntry.timestamp` is
136	        // the cache-write time (= event-firing time, writes are synchronous).
137	        const now = Date.now();
138	        const [lastTestRun, lastSelfHealing] = await Promise.all([
139	          getEventCacheEntry('test-run').catch(() => undefined),
140	          getEventCacheEntry('ai-setup-self-healing-scoring').catch(() => undefined),
141	        ]);
142	        const hasRecentTestActivity = [lastTestRun, lastSelfHealing].some(
143	          (e) => e && now - e.timestamp < AI_IDLE_DELAY_MS
144	        );
145	        if (hasRecentTestActivity) {
146	          scheduleIdleCheck();
147	          return;
148	        }
149	        // Final re-check: ai-setup may have been cached after the last trigger.
150	        await markAiSetupDone();
151	        if (store.getState().items.aiSetup?.status !== 'done') {
152	          return;
153	        }
154	        analyticsEmitted = true;
155	        channel.off(STORY_INDEX_INVALIDATED, onIndexInvalidated);
156	        unsubscribeTestProvider();
157	        channel.emit(GHOST_STORIES_REQUEST);
158	        channel.emit(AI_SETUP_ANALYTICS_REQUEST);
159	      }, AI_IDLE_DELAY_MS);
160	    };
161	
162	    // Startup check: covers the case where the dev server was restarted
163	    // mid-agentic-session and `ai-setup` was already cached.
164	    markAiSetupDone().then((detected) => {
165	      if (detected) {
166	        scheduleIdleCheck();
167	      }
168	    });
169	
170	    const onIndexInvalidated = () => {
171	      if (analyticsEmitted) {
172	        return;
173	      }
174	      scheduleIdleCheck();
175	    };
176	    if (channel) {
177	      channel.on(STORY_INDEX_INVALIDATED, onIndexInvalidated);
