181	    // long stretches running tests without touching story files. Captured so
182	    // we can unsubscribe symmetrically when analytics fires.
183	    const unsubscribeTestProvider = universalTestProviderStore.onStateChange(() => {
184	      if (analyticsEmitted) {
185	        return;
186	      }
187	      scheduleIdleCheck();
188	    });
